reconstruction_climate <- function(taxa.appear.core,which.taxa,tf.x1.current,tf.x2.current,recent){
    # mean recent climate
    if(recent){ 
        tann.recent <- weightedMedian(x1range.bck,(taxa.appear.core[1,] %*% tf.x1.current)[1,])
        pann.recent <- weightedMedian(x2range.bck,(taxa.appear.core[1,] %*% tf.x2.current)[1,])
    }else{
        tann.recent <- prior.recent$mean.tmp
        pann.recent <- prior.recent$mean.pann
    }
    # output
    return(list(tann = tann.recent, pann = pann.recent))
}
